calc.mjs.text:
// Pure gig-delivery/rideshare net-pay arithmetic. No network, no state.
//
// The app screen shows gross pay per hour. It never subtracts the one cost
// that is entirely the driver's: the car. Gas, tires, oil changes, and
// insurance do not show up anywhere in the app, so "I made $22/hour" and
// "I kept $22/hour" are treated as the same sentence when they usually are
// not. This turns one session's numbers into what actually stayed in the
// driver's pocket per mile and per hour, after the vehicle and before
// income tax — plus what to set aside for the tax nothing here withholds.
//
// Every figure is an input. The result is transparent arithmetic the driver
// can check against a fuel receipt and their own odometer — not a claim
// about what any platform, market, or trip "should" pay.

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

function optionalNumber(value, name) {
  if (value === null || value === undefined || value === "") return null;
  return number(value, name);
}

/**
 * Cost one gig-driving session (a dash, a shift, a week — whatever period
 * the figures cover) and report net pay per mile and per hour.
 *
 * @param {object} input
 * @param {number} input.grossPay        Everything the app(s) paid out this session: base pay, tips, promotions.
 * @param {number} input.milesDriven     Every mile driven this session, including the drive to go online and back home.
 * @param {number} input.hoursActive     Hours online / dashing this session.
 * @param {number} input.mpg             Vehicle's average miles per gallon.
 * @param {number} input.gasPrice        Dollars per gallon.
 * @param {number} input.maintenancePerMile Reserve for repairs, tires, and oil changes, per mile.
 * @param {number} input.insuranceMonthly   Monthly insurance cost attributable to driving for the app(s).
 * @param {number} input.otherFixedMonthly  Everything else billed monthly: phone plan, hot bag, car wash, etc.
 * @param {number} input.monthlyMiles    Typical business miles driven in a month — used to spread the two
 *   monthly figures above across this session's share of them.
 * @param {number} input.taxReservePercent Share of profit set aside for self-employment and income tax.
 *   Their number, not ours — see taxReserve below.
 * @param {number|null} input.comparisonHourlyWage Optional: another hourly wage to compare against.
 * @param {number|null} input.targetHourlyTakeHome Optional: solve for the gross pay that would leave this
 *   much per hour after vehicle cost and the tax reserve.
 */
export function calculateSession(input) {
  const grossPay = number(input.grossPay ?? 0, "Gross pay");
  const milesDriven = number(input.milesDriven ?? 0, "Miles driven");
  const hoursActive = number(input.hoursActive ?? 0, "Hours active");
  const mpg = number(input.mpg ?? 0, "Miles per gallon", { allowZero: false });
  const gasPrice = number(input.gasPrice ?? 0, "Gas price");
  const maintenancePerMile = number(input.maintenancePerMile ?? 0, "Maintenance per mile");
  const insuranceMonthly = number(input.insuranceMonthly ?? 0, "Insurance");
  const otherFixedMonthly = number(input.otherFixedMonthly ?? 0, "Other fixed cost");
  const monthlyMiles = number(input.monthlyMiles ?? 0, "Monthly miles", { allowZero: false });

  // Self-employed, so nothing withholds. Left implicit, every dollar figure
  // below would be pre-tax and read as take-home. The percentage is theirs,
  // never ours: it depends on filing status, state, deductions, and other
  // income, none of which this page asks for or should. 0 keeps every
  // figure exactly as it would be with no reserve at all.
  const taxReservePercent = number(input.taxReservePercent ?? 0, "Tax reserve");
  if (taxReservePercent >= 100) throw new Error("Tax reserve must be less than 100%");

  const comparisonHourlyWage = optionalNumber(input.comparisonHourlyWage, "Comparison hourly wage");
  const targetHourlyTakeHome = optionalNumber(input.targetHourlyTakeHome, "Target hourly take-home");

  const fuelCostPerMile = gasPrice / mpg;
  const variableCostPerMile = fuelCostPerMile + maintenancePerMile;
  const variableCost = milesDriven * variableCostPerMile;

  const monthlyFixed = insuranceMonthly + otherFixedMonthly;
  const fixedCostPerMile = monthlyFixed / monthlyMiles;
  // A no-miles session allocates none of the month's fixed cost to itself —
  // the car sat still. That fixed dollar still comes due somewhere across
  // the month; this reports one session, not the month it belongs to.
  const fixedCost = fixedCostPerMile * milesDriven;

  const vehicleCost = variableCost + fixedCost;
  const allInCostPerMile = variableCostPerMile + fixedCostPerMile;

  const netProfit = grossPay - vehicleCost;
  // Only a profitable session owes anything. A losing session is floored at
  // zero rather than generating a negative reserve that would read as a
  // refund this page is in no position to promise — a loss may offset other
  // income or carry over, which is exactly the judgement this page does not
  // make. So takeHome equals netProfit on a losing session.
  const taxReserve = Math.max(0, netProfit) * (taxReservePercent / 100);
  const takeHome = netProfit - taxReserve;

  const grossPerMile = milesDriven === 0 ? null : grossPay / milesDriven;
  const netPerMile = milesDriven === 0 ? null : netProfit / milesDriven;
  const takeHomePerMile = milesDriven === 0 ? null : takeHome / milesDriven;
  const grossPerHour = hoursActive === 0 ? null : grossPay / hoursActive;
  const netPerHour = hoursActive === 0 ? null : netProfit / hoursActive;
  const takeHomePerHour = hoursActive === 0 ? null : takeHome / hoursActive;

  const comparison = comparisonHourlyWage === null
    ? null
    : {
      comparisonHourlyWage,
      // Compared before income tax, same basis as the wage itself — a
      // minimum-wage paycheck is quoted pre-income-tax too. The vehicle
      // cost is already out of both sides of this comparison.
      gapPerHour: netPerHour === null ? null : netPerHour - comparisonHourlyWage,
      clears: netPerHour === null ? null : netPerHour >= comparisonHourlyWage,
    };

  let target = null;
  if (targetHourlyTakeHome !== null) {
    if (hoursActive === 0) {
      target = null;
    } else {
      const totalTarget = targetHourlyTakeHome * hoursActive;
      // The target is what the driver wants to keep, so it is grossed up
      // through the tax reserve before it becomes profit the session has to
      // earn: keeping $20/hr at a 25% reserve means clearing $26.67/hr
      // pre-tax, not $20/hr.
      const neededProfit = totalTarget / (1 - taxReservePercent / 100);
      const neededGrossPay = Math.max(0, vehicleCost + neededProfit);
      target = {
        targetHourlyTakeHome,
        grossPayNeeded: neededGrossPay,
        grossPerMileNeeded: milesDriven === 0 ? null : neededGrossPay / milesDriven,
        grossPerHourNeeded: neededGrossPay / hoursActive,
      };
    }
  }

  return {
    grossPay,
    milesDriven,
    hoursActive,
    fuelCostPerMile,
    variableCostPerMile,
    variableCost,
    monthlyFixed,
    fixedCostPerMile,
    fixedCost,
    vehicleCost,
    allInCostPerMile,
    netProfit,
    taxReservePercent,
    taxReserve,
    takeHome,
    grossPerMile,
    netPerMile,
    takeHomePerMile,
    grossPerHour,
    netPerHour,
    takeHomePerHour,
    comparison,
    target,
  };
}

offer.mjs.text:
// Pure accept-or-decline arithmetic for one delivery or rideshare offer. No
// network, no state.
//
// The session calculator prices a finished shift. This prices the decision a
// driver makes dozens of times a shift, before it is made: the app shows a
// payout and a distance, and nothing about what the miles will cost or how
// long the order really takes. Only the per-mile cost that moves with
// distance (fuel and wear) is charged to an offer. Insurance and phone plan
// are owed whether the offer is accepted or not, so counting them here would
// make good offers look worse than they are.
//
// Every figure is an input; nothing here is a claim about what any platform
// should pay.

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (value === "" || value === null || value === undefined || !Number.isFinite(result)) {
    throw new Error(`${name} must be a number`);
  }
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

function optional(value, name) {
  return value === "" || value === null || value === undefined ? null : number(value, name);
}

/**
 * @param {object} input
 * @param {number} input.payout            Offered pay including any guaranteed tip.
 * @param {number} input.milesToPickup     Miles from where you are to the pickup.
 * @param {number} input.milesToDropoff    Miles from pickup to drop-off.
 * @param {number} input.milesBack         Miles you expect to drive afterwards to reach a place you would
 *   be offered work again (0 if the drop-off is in a busy zone).
 * @param {number} input.minutesToPickup   Minutes to reach the pickup.
 * @param {number} input.minutesWaiting    Minutes you expect to wait at the pickup.
 * @param {number} input.minutesToDropoff  Minutes from pickup to drop-off, including handoff.
 * @param {number} input.minutesBack       Minutes of the drive back, if any.
 * @param {number} input.mpg
 * @param {number} input.gasPrice
 * @param {number} input.maintenancePerMile
 * @param {number|null} input.minNetPerHour Your floor, after the car; optional.
 * @param {number|null} input.minNetPerMile Your floor per mile driven; optional.
 */
export function evaluateOffer(input) {
  const payout = number(input.payout, "Payout");
  const milesToPickup = number(input.milesToPickup ?? 0, "Miles to pickup");
  const milesToDropoff = number(input.milesToDropoff ?? 0, "Miles to drop-off");
  const milesBack = number(input.milesBack ?? 0, "Miles back");
  const minutesToPickup = number(input.minutesToPickup ?? 0, "Minutes to pickup");
  const minutesWaiting = number(input.minutesWaiting ?? 0, "Minutes waiting");
  const minutesToDropoff = number(input.minutesToDropoff ?? 0, "Minutes to drop-off");
  const minutesBack = number(input.minutesBack ?? 0, "Minutes back");
  const mpg = number(input.mpg, "Miles per gallon", { allowZero: false });
  const gasPrice = number(input.gasPrice ?? 0, "Gas price");
  const maintenancePerMile = number(input.maintenancePerMile ?? 0, "Maintenance per mile");
  const minNetPerHour = optional(input.minNetPerHour, "Minimum net per hour");
  const minNetPerMile = optional(input.minNetPerMile, "Minimum net per mile");

  const miles = milesToPickup + milesToDropoff + milesBack;
  const minutes = minutesToPickup + minutesWaiting + minutesToDropoff + minutesBack;
  const hours = minutes / 60;

  const costPerMile = gasPrice / mpg + maintenancePerMile;
  const vehicleCost = miles * costPerMile;
  const net = payout - vehicleCost;

  const grossPerMile = miles === 0 ? null : payout / miles;
  const netPerMile = miles === 0 ? null : net / miles;
  const grossPerHour = hours === 0 ? null : payout / hours;
  const netPerHour = hours === 0 ? null : net / hours;

  // Lowest payout that clears every floor the driver set. With no floor set
  // there is nothing to solve for, so it is null rather than the break-even.
  const floors = [];
  if (minNetPerHour !== null) floors.push(vehicleCost + minNetPerHour * hours);
  if (minNetPerMile !== null) floors.push(vehicleCost + minNetPerMile * miles);
  const minPayout = floors.length === 0 ? null : Math.max(...floors);

  const failures = [];
  if (minNetPerHour !== null && (netPerHour === null || netPerHour < minNetPerHour)) failures.push("hour");
  if (minNetPerMile !== null && (netPerMile === null || netPerMile < minNetPerMile)) failures.push("mile");

  let verdict;
  if (minPayout === null) verdict = net >= 0 ? "no-floor-profit" : "no-floor-loss";
  else verdict = failures.length === 0 ? "accept" : "decline";

  return {
    payout, miles, minutes, hours, costPerMile, vehicleCost, net,
    grossPerMile, netPerMile, grossPerHour, netPerHour,
    minPayout,
    shortfall: minPayout === null ? null : Math.max(0, minPayout - payout),
    failures,
    verdict,
  };
}

share.mjs.text:
// Shareable session link.
//
// A link that reopens the calculator with the same numbers already in it
// lets a partner, a spouse doing the household books, or future-you try a
// different gas price or a different session's miles against the same
// vehicle-cost assumptions, instead of retyping ten figures from a text
// message.
//
// The transform is pure -- no DOM, no storage, no network -- and the page
// puts the payload in the URL fragment, which browsers never send to a
// server. Gross pay, miles, and vehicle costs stay on the two devices the
// link is pasted between, the same promise the rest of this calculator
// makes.

/** Mirrors `FIELD_IDS` in `index.html`. */
export const NUMBER_FIELD_IDS = Object.freeze([
  "grossPay", "milesDriven", "hoursActive", "mpg", "gasPrice",
  "maintenancePerMile", "insuranceMonthly", "otherFixedMonthly", "monthlyMiles",
  "taxReservePercent", "comparisonHourlyWage", "targetHourlyTakeHome",
]);

// `usageOptOut` is deliberately absent, same reasoning as every other share
// link in this fleet: it is the recipient's own privacy choice about their
// own browser, and a sender should not be able to switch counting back on --
// or off -- for someone else by handing them a link.

function usableNumber(value) {
  if (value === "" || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

/**
 * Encode the page's current inputs as a URL fragment payload.
 *
 * Blank and unusable fields are omitted rather than sent as empty strings, so
 * the recipient's page keeps its own starting default for anything the
 * sender left alone instead of being handed a field it must treat as zero.
 */
export function encodeInputs(inputs) {
  const params = new URLSearchParams();
  for (const id of NUMBER_FIELD_IDS) {
    const value = usableNumber(inputs?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  return params.toString();
}

/**
 * Read a fragment (or query string) back into an input map.
 *
 * Anything unrecognised, negative, or non-numeric is dropped rather than
 * throwing: a truncated link pasted into a text message should open the page
 * on the fields that survived, not on an error.
 */
export function decodeInputs(source) {
  if (typeof source !== "string") return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ""));
  const inputs = {};
  for (const id of NUMBER_FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) inputs[id] = value;
  }
  return inputs;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores gross
// pay, miles, gas price, or any other input, and it never leaves the device
// — a driver's earnings are exactly the sort of thing that must not be
// transmitted anywhere.
function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'session_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  const today = new Date().toISOString().slice(0, 10);
  const current = JSON.parse(storage.getItem('gig-driver-net-pay-usage') || '{}');
  current[event] = (current[event] || 0) + 1;
  current.last_day = today;
  storage.setItem('gig-driver-net-pay-usage', JSON.stringify(current));
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem('gig-driver-net-pay-usage-opt-out') === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem('gig-driver-net-pay-usage'); } catch { /* storage is optional */ }
    try { storage.setItem('gig-driver-net-pay-usage-opt-out', '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem('gig-driver-net-pay-usage-opt-out'); } catch { /* storage is optional */ }
  }
}
